import{S as r,o as n,c as a,a9 as d,B as c}from"./chunks/framework.DxG24V0C.js";const s="/agentsrc/images/opencode/article-01-layers.svg",i="/agentsrc/images/opencode/article-01-chain.svg",l="/agentsrc/images/opencode/article-01-extensions.svg",m=JSON.parse('{"title":"OpenCode 整体架构：一个 10 万行 Agent 怎么被组织成一条装配链","description":"","frontmatter":{"title":"OpenCode 整体架构：一个 10 万行 Agent 怎么被组织成一条装配链"},"headers":[],"relativePath":"opencode/01-overview.md","filePath":"opencode/01-overview.md","lastUpdated":1787409644000}'),p={name:"opencode/01-overview.md"},b=Object.assign(p,{setup(g){const o=[{question:"OpenCode 把引擎拆成 core / llm / opencode 三包，依赖方向最准确的是？",options:["'opencode' 依赖 'core' 与 'llm'，'core' 做底座不依赖任何内部包，'llm' 独立协议层","'core' 依赖 'opencode' 和 'llm'，因为实现要在契约之上","三个包互相循环依赖，谁都依赖谁，靠 Effect 解耦","'llm' 是最底层，反过来依赖 'opencode' 的运行时才能找回厂商"],correct:0,explanation:"core 是最底底座（无内部依赖），llm 独立中立，opencode 依赖 core+llm+sdk+plugin+ui 做装配。三个包依赖方向清晰单向，才能化整为零。"},{question:"厂商接入的核心设计是什么？",options:["在代码里写死 N 家厂商标记，硬编码判断走哪个","core/plugin/provider 里放 N 个适配器，向 core 插一个即可接入新厂商","model 不作为变量，每个厂商一个独立分支的 prompt 模板","用一个巨型条件分支在运行时逐个判断走哪家模型"],correct:1,explanation:"厂商接入是「往 core 的 provider/ 目录插 adapter」的可插拔方式，所以能接 30+ 家而不乱。选项 A/D 是静态写死，C 与事实不符。"},{question:"关于「单一入口」，正确的是？",options:["CLI 和 Web 用两套独立引擎分别实现，入口不同需要并行维护两份","有一个 index.ts 一个代码入口，它是唯一 CLI 入口（yargs 装 20+ 子命令），跑 serve 同进程开 HTTP + WebSocket","入口只有一个 serve 命令，不支持 CLI，必须走 HTTP","每个子命令都编译成一个独立二进制，无共享装配"],correct:1,explanation:"cli 和 web 等等是同一套引擎同一入口，靠 index.ts(serve 等子命令)装配，同进程开出 HTTP API 和 WebSocket。"},{question:"把持久化用 SQLite + Drizzle 做，而非 JSONL，主要说明什么抽象？",options:["它是 append-only 的纯文本，适合日志级的顺序追加与手工翻阅","它把会话状态落到可结构化查询的底座，能审计能恢复","它牺牲查询能力换取最小的安装体积，只承担轻量存取不是会话续命","它只适合单机一次性写入，无法支撑多次会话之间的状态重建"],correct:1,explanation:"SQLite + Drizzle 支撑结构化查询与事务，让会话状态能审计、能恢复，而不是只靠 append-only JSONL 的手工可读。"},{question:"「装配链」为什么是开这篇的核心？",options:["证明主循环写得足够漂亮，靠一条循环就能压住 Agent 的随意输出","把复杂度切成「入口→运行时→主循环→工具→持久化/扩展」各段，层层可替换，才得以大而不乱","证明这个项目的代码行数全网最少，所以读起来天然轻松","证明单个模型足够强大，一套提示词就能统摄所有子系统的细节"],correct:1,explanation:"核心哲学：靠一条可断可换、各守一段的装配链把快 10 万行化整为零，架构追求「大纲美」而非一行代码。"}];return(h,e)=>{const t=r("Quiz");return n(),a("div",null,[e[0]||(e[0]=d('<h1 id="opencode-整体架构-一个-10-万行-agent-怎么被组织成一条装配链" tabindex="-1">OpenCode 整体架构：一个 10 万行 Agent 怎么被组织成一条装配链 <a class="header-anchor" href="#opencode-整体架构-一个-10-万行-agent-怎么被组织成一条装配链" aria-label="Permalink to &quot;OpenCode 整体架构：一个 10 万行 Agent 怎么被组织成一条装配链&quot;">​</a></h1><p>如果一个终端里能跑的 AI 编程助手，源码拆成几十个包、上万个文件，能接 <strong>30 多家模型厂商</strong>，还要在同一个进程里把命令行、HTTP 接口、WebSocket、插件、快照挨个伺候好……</p><p>它凭什么不乱？</p><p>先停一下。假如让你来设计这个东西，你会从哪儿下手？大多数人第一反应是「先写 <code>runLoop</code>，让模型能一轮轮转起来」。但真到几万行的规模你会发现，<strong>让系统不塌的，往往不是某一个主循环，而是它怎么被组织成一条「装配链」</strong>：入口、运行时、模型、持久化、扩展，每一段守好自己那一段，再拼成一个可运行的整体。这篇的任务，就是先把这张总地图搭起来。</p><p>看完这篇，你会 get 到三个问题：</p><ul><li>第一，这个 10 万行引擎被拆成了哪几块，为什么是「契约 / 模型 / 实现」三体；</li><li>第二，一个命令从你手上按下，是怎么被<strong>装配成一条能跑起来的链</strong>的；</li><li>第三，持久化和扩展是怎么长出来、却不把主干拖乱的。</li></ul><p>这一篇先从「设计一个通用 Agent 引擎到底要摊开哪些摊子」说起。主循环、工具和上下文这些细部机制，放到后面的文章再往下拆。</p><h2 id="一、先把问题摆出来-做一个「通用-agent-引擎」的摊子有多大" tabindex="-1">一、先把问题摆出来：做一个「通用 Agent 引擎」的摊子有多大 <a class="header-anchor" href="#一、先把问题摆出来-做一个「通用-agent-引擎」的摊子有多大" aria-label="Permalink to &quot;一、先把问题摆出来：做一个「通用 Agent 引擎」的摊子有多大&quot;">​</a></h2><h3 id="_1-1-一个能想象的任务" tabindex="-1">1.1 一个能想象的任务 <a class="header-anchor" href="#_1-1-一个能想象的任务" aria-label="Permalink to &quot;1.1 一个能想象的任务&quot;">​</a></h3><p>想象你被要求做一个<strong>通用的、开源可扩展的终端编程 Agent</strong>。不是给自家某个模型写个玩具，而是要让它：</p><ul><li>能接<strong>几十家不同厂商的模型</strong>——Anthropic、OpenAI、Google、以及一堆开源可兼容的协议端点；</li><li>既能当 <strong>CLI 命令行</strong>跑，又能被 <strong>Web / SDK</strong> 拉起来当服务；</li><li>还得让人<strong>写插件扩展</strong>它的行为，而不需要改它核心。</li></ul><p>在你动手敲第一行 <code>run()</code> 之前，先把这件事摊开看：<strong>它不是一个「循环」，而是四类完全不同的负担叠在一起</strong>——模型差异、运行时主循环、持久化、可扩展性。</p><h3 id="_1-2-先拆出四类负担" tabindex="-1">1.2 先拆出四类负担 <a class="header-anchor" href="#_1-2-先拆出四类负担" aria-label="Permalink to &quot;1.2 先拆出四类负担&quot;">​</a></h3><p>把「通用 Agent 引擎」的复杂度摊到桌面上，其实是四堆互不相干的问题：</p><table tabindex="0"><thead><tr><th>负担</th><th>它的本质</th><th>要回答的问题</th></tr></thead><tbody><tr><td><strong>模型差异</strong></td><td>各家厂商的接口、协议、能力都不一样</td><td>怎么用一个抽象把几十家 <code>说得不同</code> 的模型统一进来</td></tr><tr><td><strong>运行时主循环</strong></td><td>模型不是一次性，是要「感知→分析→行动→反馈」反复迭代</td><td>这个迭代的骨架怎么保持着，又不散落一地</td></tr><tr><td><strong>持久化</strong></td><td>Agent 是一次又一次的会话，中途崩了要能续上</td><td>状态存哪、怎么查、怎么升级</td></tr><tr><td><strong>可扩展</strong></td><td>第三方要能用、能改</td><td>怎么让别人叠加能力而不改内核</td></tr></tbody></table><p>这四个问题，正是后面所有章节要解决的四个「为什么」。而 OpenCode 给的答案有一个共同的形式：<strong>把每一种负担，都变成一个独立的、可替换的「层次」，再用一条装配链把它们拼起来。</strong> 先把引擎本身分成哪几块讲清楚。</p><h2 id="二、三大引擎包-为什么是「契约-模型-实现」三体" tabindex="-1">二、三大引擎包：为什么是「契约 / 模型 / 实现」三体 <a class="header-anchor" href="#二、三大引擎包-为什么是「契约-模型-实现」三体" aria-label="Permalink to &quot;二、三大引擎包：为什么是「契约 / 模型 / 实现」三体&quot;">​</a></h2><p>先看 OpenCode 真正的代码骨架。它不是一个包包打天下的巨石，而是一个有边界、有依赖方向的 monorepo——核心引擎由三个包构成：<code>core</code>、<code>llm</code>、<code>opencode</code>。</p><h3 id="_2-1-core-契约-厂商接入基座-是整个系统的底座" tabindex="-1">2.1 <code>core</code>：契约 + 厂商接入基座，是整个系统的底座 <a class="header-anchor" href="#_2-1-core-契约-厂商接入基座-是整个系统的底座" aria-label="Permalink to &quot;2.1 `core`：契约 + 厂商接入基座，是整个系统的底座&quot;">​</a></h3><p><code>packages/core</code> 是整个系统最底的一层基座。它放的东西有两类：</p><ul><li><strong>类型与契约</strong>：<code>session</code>、<code>message</code>、<code>agent</code>、<code>model</code>、<code>tool-output</code>、<code>provider</code>……这些是系统的「名词表」，规定“一个会话长什么样”“一个模型长什么样”。</li><li><strong>厂商接入基座</strong>：它的 <code>src/plugin/provider/</code> 下放了 <strong>30+ 个 Provider 适配器</strong>（Anthropic、OpenAI、Google、Bedrock、Azure、以及一堆 openai-compatible、openrouter、togetherai……），每个都是一个「把一个厂商装进系统」的接线器。</li></ul><p>这就点破一层：<strong>厂商接入 OpenCode 不是「写死在代码里的 N 家」，而是「往基座上插一个适配器」</strong>。你想支持一个新厂商，代码量不至于很小——新写一个 adapter，在 <code>provider/</code> 目录挂上即可。这是它能「接得住 30 多家」而代码不乱的根本原因。</p><h3 id="_2-2-llm-独立的模型协议层-把「厂商协议」抽象成可换的一块" tabindex="-1">2.2 <code>llm</code>：独立的模型协议层，把「厂商协议」抽象成可换的一块 <a class="header-anchor" href="#_2-2-llm-独立的模型协议层-把「厂商协议」抽象成可换的一块" aria-label="Permalink to &quot;2.2 `llm`：独立的模型协议层，把「厂商协议」抽象成可换的一块&quot;">​</a></h3><p>如果你注意上一条，会发现模型相关的逻辑其实有两层：一层是「每个厂商怎么接」（core 的 adapter），另一层是「怎么按协议对齐」。OpenCode 把它单独抽成 <code>packages/llm</code>。</p><p><code>llm</code> 包是个<strong>独立的模型协议层</strong>——它把各家厂商的报文、认证、路由整理到底层的公共 abstraction（Protocol / Endpoint / Auth / Framing 四个维度），依赖面很轻、基本只与基础件（如 <code>effect</code>）耦合，不和 session、运行时缠绕。它的存在意味着：<strong>「模型怎么接」这件事，是整个引擎里可以独立演进、独立替换的一块</strong>。这不是实现细节，而是设计上的一个刻意分层决策：模型层的稳定性，不该被运行时里那些频繁变动的逻辑一起裹挟。</p><h3 id="_2-3-opencode-所有「运行时实现」的家" tabindex="-1">2.3 <code>opencode</code>：所有「运行时实现」的家 <a class="header-anchor" href="#_2-3-opencode-所有「运行时实现」的家" aria-label="Permalink to &quot;2.3 `opencode`：所有「运行时实现」的家&quot;">​</a></h3><p><code>packages/opencode</code> 是三个包里最大的一块，也是<strong>真正干活的引擎</strong>：<code>session/</code>（会话与主循环）、<code>tool/</code>（几十个内置工具）、<code>server/</code>（HTTP 服务）、<code>mcp/</code>、<code>skill/</code>、<code>snapshot/</code>、<code>storage/</code>（SQLite 持久化）、<code>git/</code>、<code>permission/</code>……几乎除了「契约」和「纯模型协议」之外，一切实现都在这里。</p><h3 id="_2-4-三者怎么咬合-依赖方向决定「谁在底座」" tabindex="-1">2.4 三者怎么咬合：依赖方向决定「谁在底座」 <a class="header-anchor" href="#_2-4-三者怎么咬合-依赖方向决定「谁在底座」" aria-label="Permalink to &quot;2.4 三者怎么咬合：依赖方向决定「谁在底座」&quot;">​</a></h3><p>把三块放一起，依赖方向非常清晰：</p><ul><li><code>core</code> 在<strong>最底</strong>，什么都不依赖（不依赖任何内部包，只靠纯 npm 外部件）；</li><li><code>llm</code> <strong>独立中立</strong>，也和内部无强耦合；</li><li><code>opencode</code> 在<strong>最顶</strong>，同时依赖 <code>core</code>、<code>llm</code>、<code>sdk</code>、<code>plugin</code>、<code>ui</code>、<code>script</code> 等内部包——它是「装配链」上把别的包拼成一个可运行品的那一段。</li></ul><p>大小上看（按 <code>src</code> 下 TypeScript 计）：<code>core</code> ≈ 1.2 万行、<code>llm</code> ≈ 8.7 千行、<code>opencode</code> ≈ 8.7 万行——三包合计约 10 万行量级，其中实现层占了绝大部分。</p><p>顺着这条装配链，我们先把「层怎么分、链怎么接」看清楚。</p><p><img src="'+s+'" alt="Three Core Layers"></p><h2 id="三、一条装配链-从你敲命令到它跑起来" tabindex="-1">三、一条装配链：从你敲命令到它跑起来 <a class="header-anchor" href="#三、一条装配链-从你敲命令到它跑起来" aria-label="Permalink to &quot;三、一条装配链：从你敲命令到它跑起来&quot;">​</a></h2><p>三块放在那还只是一堆包；真正让系统活起来的，是它们被<strong>装配成一条链</strong>。这条链的入口只有一主。</p><h3 id="_3-1-单一入口-一个-index-ts-拉起整个运行时" tabindex="-1">3.1 单一入口：一个 <code>index.ts</code> 拉起整个运行时 <a class="header-anchor" href="#_3-1-单一入口-一个-index-ts-拉起整个运行时" aria-label="Permalink to &quot;3.1 单一入口：一个 `index.ts` 拉起整个运行时&quot;">​</a></h3><p><code>packages/opencode/src/index.ts</code> 是唯一入口，用 yargs 装好 20+ 个子命令（run / serve / tui / acp / mcp / providers / agent / …）。真正长驻的是 <code>serve</code>：它拉起一个 <strong>Engine runtime</strong>（Effect 装配的运行时），同一个进程里同时把 <strong>HTTP API</strong> 和 <strong>WebSocket</strong> 两个面开出来。</p><ul><li>这也意味着：终端里敲 <code>opencode</code>(CLI) 和网页里连它 (Web/HTTP) 是<strong>同一套引擎</strong>，只是面不同入口——设计上省了一大份「双实现」。</li></ul><h3 id="_3-2-会话主循环-一条可以被反复走的循环" tabindex="-1">3.2 会话主循环：一条可以被反复走的循环 <a class="header-anchor" href="#_3-2-会话主循环-一条可以被反复走的循环" aria-label="Permalink to &quot;3.2 会话主循环：一条可以被反复走的循环&quot;">​</a></h3><p>引擎起来之后，核心是 <code>session</code> 里的主循环（<code>session/processor.ts</code>）：它承接一个 prompt，进入「感知 → 分析 → 行动 → 反馈」的迭代，直到模型决定停下来/输出。工具的执行、压缩的触发（上下文溢出）都在这个循环里被安排。</p><p>这一篇先停在这张总图上。<strong>你先抓住一点：它是那条「装配链」的中心骨，所有其它层（模型、工具、持久化、插件）都挂在它身上来回打转。</strong> 具体到每一格怎么走、事件怎么处理，放到后面的文章再拆。</p><h3 id="_3-3-一条链的结果-各守一段-化整为零" tabindex="-1">3.3 一条链的结果：各守一段，化整为零 <a class="header-anchor" href="#_3-3-一条链的结果-各守一段-化整为零" aria-label="Permalink to &quot;3.3 一条链的结果：各守一段，化整为零&quot;">​</a></h3><p>把上往下整个走一遍： <strong>入口（index.ts/serve）→ 运行时 → 会话主循环（processor）→ 模型（core adapter + llm）→ 工具执行 → SQLite 持久化 / plugin-mcp-skill 扩展</strong>。</p><p>每一步都清楚自己「从谁手里接、往谁手里送」。换句话说，节点各守一段，接口清楚，单点替换也不至于把整套系统一起带歪。</p><p><img src="'+i+'" alt="One Assembly Chain"></p><h2 id="四、持久化与扩展-状态怎么落地-能力怎么外挂" tabindex="-1">四、持久化与扩展：状态怎么落地，能力怎么外挂 <a class="header-anchor" href="#四、持久化与扩展-状态怎么落地-能力怎么外挂" aria-label="Permalink to &quot;四、持久化与扩展：状态怎么落地，能力怎么外挂&quot;">​</a></h2><p>装好了主链之后，还有两块把「系统从能跑到可用」补齐：持久化让你能续、扩展让你能长。</p><h3 id="_4-1-持久化-状态可查-还能安全升级" tabindex="-1">4.1 持久化：状态可查，还能安全升级 <a class="header-anchor" href="#_4-1-持久化-状态可查-还能安全升级" aria-label="Permalink to &quot;4.1 持久化：状态可查，还能安全升级&quot;">​</a></h3><p>Agent 是反复的会话，状态不能都压在内存。OpenCode 用 <strong>SQLite + Drizzle</strong> 做持久化（schema 在 <code>session.sql.ts</code> / <code>storage</code> 里定义）。这里想说的是一个抽象：<strong>把状态「落到更可查询的结构」，而不是 append-only 的纯文本</strong>——这样程序能审计、能恢复。</p><h3 id="_4-2-扩展面-改行为指针不动核心" tabindex="-1">4.2 扩展面：改行为指针不动核心 <a class="header-anchor" href="#_4-2-扩展面-改行为指针不动核心" aria-label="Permalink to &quot;4.2 扩展面：改行为指针不动核心&quot;">​</a></h3><p>它让第三方能扩展，靠的是 <code>plugin</code>（公共包，供外部插件作者用）+ <code>mcp</code> + <code>skill</code> + <code>snapshot</code> + <code>background</code> 这些挂在运行时之上的能力。关键是：<strong>你要叠加一个新能力，不需要碰核心引擎</strong>——插件做成一个「机制」外挂在运行时，还受 <code>permission</code> 约束。这和后面聊 plan-execute-verify 时「插件在原生 hook 上叠加策略」的思路是一脉相承的。</p><p><img src="'+l+'" alt="Core and Extensions"></p><h2 id="五、这套分层最后留下了什么" tabindex="-1">五、这套分层最后留下了什么 <a class="header-anchor" href="#五、这套分层最后留下了什么" aria-label="Permalink to &quot;五、这套分层最后留下了什么&quot;">​</a></h2><h3 id="_5-1-五条好用的抽象" tabindex="-1">5.1 五条好用的抽象 <a class="header-anchor" href="#_5-1-五条好用的抽象" aria-label="Permalink to &quot;5.1 五条好用的抽象&quot;">​</a></h3><p>回头看整篇，这套体系更值得带走的，是五条抽象，而不是某段代码：</p><ol><li><strong>契约底座先行</strong>：<code>core</code> 只放类型与厂商接入基座，不依赖任何内部包——「名词」和「动词」分干净。</li><li><strong>模型层独立</strong>：<code>llm</code> 把厂商协议独立成包，模型接入是可评测、可换的。</li><li><strong>单一入口</strong>：CLI 和 Web 用同一引擎，一个 <code>index.ts</code> 装配起所有子命令。</li><li><strong>一条装配链</strong>：入口 → 运行时 → 会话主循环 → 工具 → 持久化 / 扩展，层层咬合。</li><li><strong>扩展不拆</strong>：插件 / mcp / skill 栓在运行时外围，受 permission 门控，不动内核。</li></ol><h3 id="_5-2-设计哲学-复杂度先切层-再谈规模" tabindex="-1">5.2 设计哲学：复杂度先切层，再谈规模 <a class="header-anchor" href="#_5-2-设计哲学-复杂度先切层-再谈规模" aria-label="Permalink to &quot;5.2 设计哲学：复杂度先切层，再谈规模&quot;">​</a></h3><p>把这些条反过来看，OpenCode 的设计哲学可以压成一句话：<strong>一个系统能做大而不乱，靠的不是某一行代码，而是有没有一开始就把复杂度切成有边界的层次，以及每层是否只守一件事。</strong></p><p>它把全栈用 <strong>Effect</strong> 一统（贯穿 core 的 Schema、opencode 的运行时装配、HTTP 服务），依赖注入和声明式装配也因此能一路贯通。模块一多，这种写法反而更稳：引擎是「装配出来的」，不是「内联写死」的。</p><h2 id="章节小测" tabindex="-1">章节小测 <a class="header-anchor" href="#章节小测" aria-label="Permalink to &quot;章节小测&quot;">​</a></h2>',60)),c(t,{questions:o})])}}});export{m as __pageData,b as default};
